<div class="repeatable-row settings-field-row" data-settings-field>
    <label class="field"><span>Field key</span><input name="farmer_fields[{{ $index }}][key]" value="{{ old("farmer_fields.$index.key", $field['key'] ?? '') }}" pattern="[a-z][a-z0-9_]{0,39}" placeholder="e.g. preferred_crop" required @disabled(! auth()->user()->canUseButton('settings.fields'))></label>
